/** Lockup A — Buccaneer on one line. Header only. */
export function WordmarkA() {
  return (
    <svg className="b2-wm b2-wm--a" viewBox="0 0 673 150.6" aria-hidden="true" focusable="false">
      <path fill="var(--wm)" d={A_D} />
    </svg>
  );
}

/** Lockup B (cartel) defined once; the hero and the footer <use> it. */
export function WordmarkBSymbol() {
  return (
    <svg width="0" height="0" aria-hidden="true" focusable="false" style={{ position: 'absolute' }}>
      <symbol id="b2-wmb" viewBox="0 0 690.4 219.8">
        <path fill="var(--wm)" d={B_TOP} />
        <path fill="var(--wm-diner)" d={B_DINER} />
      </symbol>
    </svg>
  );
}

/** Lockup B. In the hero it is decorative (the name is in the H1, AD 25.5). */
export function WordmarkB({ id, decorative = false }: { id?: string; decorative?: boolean }) {
  return (
    <svg
      id={id}
      className={decorative ? 'b2-wm b2-wm--b b2-wm--hero' : 'b2-wm b2-wm--b'}
      viewBox="0 0 690.4 219.8"
      focusable="false"
      {...(decorative ? { 'aria-hidden': true } : { role: 'img', 'aria-label': 'Buccaneer Diner' })}
    >
      <use href="#b2-wmb" />
    </svg>
  );
}

export function PhoneIcon() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M6.6 3h3.2l1.5 4.1-2 1.4a10.5 10.5 0 0 0 5.2 5.2l1.4-2L20 13.2v3.2a2 2 0 0 1-2.2 2A15.5 15.5 0 0 1 4.6 5.2 2 2 0 0 1 6.6 3Z"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function MapPin() {
  return (
    <svg className="b2-pin" width="32" height="40" viewBox="0 0 32 40" aria-hidden="true">
      <path
        d="M16 2C8.8 2 3 7.6 3 14.6 3 24 16 38 16 38s13-14 13-23.4C29 7.6 23.2 2 16 2Z"
        fill="var(--b2-neon)"
        stroke="var(--b2-paper)"
        strokeWidth="2"
      />
      <circle cx="16" cy="14.5" r="4.5" fill="var(--b2-paper)" />
    </svg>
  );
}
